css:
@page {
  size: A4;
  margin: 12mm 10mm;
}

html,
body {
  width: 210mm;
  margin: 0;
  font-family: "Arial", sans-serif;
  color: #000;
}

.po-wrapper {
  width: 190mm;
  max-width: 190mm;
  margin: 0 auto;
  padding: 6mm 8mm 8mm;
  box-sizing: border-box;
  font-size: 11px;
}

.top-section {
  margin-bottom: 12px;
}

.title-row {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  margin-bottom: 30px;
}

.title-row .logo {
  width: 95px;
  height: auto;
  position: absolute;
  left: 0;
}

.po-title {
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 1px;
  text-align: center;
  margin: 0;
  padding: 0;
  flex: 1;
}

.header-grid {
  display: grid;
  grid-template-columns: 2.2fr 1.4fr;
  gap: 12px;
  align-items: start;
  margin-bottom: 8px;
}

.company-block {
  display: flex;
  flex-direction: column;
}

.company-info {
  font-size: 10px;
  line-height: 1.5;
  text-transform: uppercase;
  margin-top: 30px;
}

.company-info strong {
  font-size: 14px;
}

.header-divider {
  border-bottom: 2px solid #006400;
  width: 100%;
  margin-top: 8px;
}

.meta-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 10px;
}

.meta-table td {
  border: 1px solid #000;
  padding: 4px 6px;
}

.meta-table td:last-child {
  color: #d32f2f;
  font-weight: 500;
}

.meta-label {
  font-weight: 600;
  width: 55%;
}

.info-row {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  margin-top: 12px;
}

.info-block {
  border: 1px solid #000;
}

.info-block .title {
  background: #dcdcdc;
  font-weight: 600;
  padding: 4px 6px;
  letter-spacing: 0.5px;
}

.info-block .body {
  min-height: 12px;
  padding: 6px;
  font-size: 10px;
  line-height: 1.4;
  text-transform: uppercase;
}

.info-block .body strong {
  font-weight: 700;
  display: block;
  margin-bottom: 2px;
}

.items-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 14px;
  font-size: 10px;
  table-layout: fixed;
}

.items-table th,
.items-table td {
  border: 1px solid #000;
  padding: 4px 5px;
}

.items-table th {
  background: #dcdcdc;
  font-weight: 700;
  letter-spacing: 0.3px;
}

.items-table thead {
  display: table-header-group;
}

.col-no {
  width: 35px;
  text-align: center;
}

.col-code {
  width: 90px;
  word-break: break-all;
  word-wrap: break-word;
}

.col-description {
  word-break: break-all;
  word-wrap: break-word;
}

.col-qty {
  width: 70px;
  text-align: center;
}

.col-unit {
  width: 60px;
  text-align: center;
}

.col-price,
.col-total {
  width: 80px;
  text-align: right;
}

.comments-grid {
  display: grid;
  grid-template-columns: 2.2fr 0.9fr;
  gap: 12px;
  margin-top: 10px;
}

.comments-block {
  border: 1px solid #000;
  min-height: 70px;
}

.comments-block .title {
  background: #dcdcdc;
  font-weight: 600;
  padding: 4px 6px;
  text-transform: uppercase;
}

.comments-block .body {
  padding: 6px;
  min-height: 50px;
}

.summary-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 10px;
}

.summary-table td {
  border: 1px solid #000;
  padding: 4px 6px;
}

.summary-table td:first-child {
  text-align: right;
  font-weight: 600;
}

.summary-table tr:last-child td {
  font-weight: 700;
  background: #f4f4f4;
}


.shelf-life {
  display: flex;
  margin-top: 12px;
  border: 1px solid #000;
  border-bottom: none;
}
.delivery{
  margin-top: 0px;
}
.delivery.transfer{
  border-bottom: 1px solid #000;
}

.shelf-life .title {
  background: #dcdcdc;
  padding: 4px 6px;
  font-weight: 600;
  text-transform: uppercase;
}

.shelf-life .body {
  padding: 6px;
  font-size: 10px;
}

.note {
  margin-top: 30px;
  font-size: 9px;
  line-height: 1.4;
  text-transform: uppercase;
}
.note div {
  text-align: center;
}

.signature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  text-align: center;
  margin-top: 30px;
  font-size: 10px;
}

.signature-grid .line {
  border-top: 1px dotted #000;
  padding-top: 6px;
  /* min-height: 10px; */
}

.signature-grid span {
  display: block;
  margin-top: 6px;
}
